
.ls-judge {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 14px;
  width: 100%;
  max-width: 620px;
  margin: 0 auto 16px;
  padding: 16px;
  border: 1px solid var(--ls-border);
  border-radius: var(--ls-r-md);
  background: var(--ls-surface);
  animation: ls-enter 0.4s var(--ls-ease-out) both;
}

.ls-judge-head {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 22px;
}

.ls-judge-event {
  font-size: 13px;
  color: var(--ls-text-body);
}

.ls-judge-outcome {
  margin-left: auto;
  padding: 1px 10px;
  border-radius: 999px;
  background: var(--ls-bg-alt);
  font-size: 12px;
  font-weight: 500;
  color: var(--ls-text-muted);
}

.ls-judge-outcome[data-outcome='大成功'],
.ls-judge-outcome[data-outcome='成功'] {
  color: var(--ls-positive);
}

.ls-judge-outcome[data-outcome='大失败'] {
  color: var(--ls-alarm);
}

/* 容器高度取徽章高度，条在其中垂直居中，徽章不会溢出到卡片的留白区 */
.ls-judge-gauge {
  position: relative;
  display: flex;
  align-items: center;
  height: 22px;
}

.ls-judge-track {
  display: flex;
  width: 100%;
  height: 10px;
  border-radius: 999px;
  overflow: hidden;
  background: var(--ls-bg-alt);
}

.ls-seg {
  height: 100%;
}

/* 四段各有颜色：两端区用深色语义色，中间两段用浅色，骰值落在哪一段一眼可辨 */
.ls-seg[data-kind='大失败'] {
  background: var(--ls-alarm);
  opacity: 0.55;
}

.ls-seg[data-kind='失败'] {
  background: var(--ls-border-strong);
}

.ls-seg[data-kind='成功'] {
  background: var(--ls-positive);
  opacity: 0.55;
}

.ls-seg[data-kind='大成功'] {
  background: var(--ls-positive);
}

/* 骰值做成骑在区间条上的胶囊徽章，用品牌橙，白描边把它与条分开 */
.ls-pin {
  position: absolute;
  top: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  height: 22px;
  padding: 0 7px;
  border-radius: 999px;
  background: var(--ls-accent);
  color: #fff;
  font-family: var(--ls-f-mono);
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 0 3px var(--ls-surface);
}

@media (max-width: 480px) {
  .ls-judge {
    gap: 16px;
    margin-bottom: 12px;
    padding: 11px 13px 14px;
    border-radius: var(--ls-r-sm);
  }
}
